                *p++ = '\r';
                break;
            case 't':
                *p++ = '\t';
                break;
            case 'v':
                *p++ = '\v';
                break;
            case '\\':
            case '\'':
                *p++ = *pstr;
                break;
            case '0':
            case '1':
            case '2':
            case '3':
            case '4':
            case '5':
            case '6':
            case '7': {
                int octnum = 0;
                int i;
                for (i = 0; i < (3 + (percent && *pstr == '0')); i++) {
                    if (*pstr < '0' || *pstr > '7')
                        break;
