                    pstr++;
                }
                pstr--;
                if (percent && octnum == '%') {
                    *p++ = '%';
                    *p++ = '%';
                } else {
                    *p++ = octnum;
                }
                break;
            }
            case 'c':
                if (percent) {
                    *p++ = *pstr;
